# SOXI handling
def handle_soxi(prog, args):
    verbosity = 2
    show_totals = False
    mode = None
    infiles = []
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--":
            i+=1
            while i < len(args):
                infiles.append(args[i]); i+=1
            break
        if a.startswith("--"):
            sys.stderr.write(f"{prog} WARN getopt: option `-' not recognized\n")
            sys.stdout.buffer.write(replace_prefix(SOXI_HELP, prog))
            sys.stdout.buffer.flush()
            sys.exit(1)
        elif a.startswith("-") and a != "-":
            if len(a) >=2 and a[1]=='V':
                rest = a[2:]
                if rest == "":
                    verbosity = 3
                else:
                    try: verbosity = int(rest)
                    except: verbosity = 2
                i+=1
                continue
            else:
                chars = a[1:]
                idx = 0
                while idx < len(chars):
                    ch = chars[idx]
                    if ch == 'V':
                        rest = chars[idx+1:]
                        if rest != "" and rest.isdigit():
                            verbosity = int(rest)
                            idx = len(chars)
                        else:
                            verbosity = 3
                            idx+=1
                    elif ch == 'T':
                        show_totals = True
                        idx+=1
                    elif ch in "trcsdDbBpea":
                        mode = ch
                        idx+=1
                    elif ch == 'h' or ch=='-':
                        sys.stderr.write(f"{prog} WARN getopt: option `{ch}' not recognized\n")
                        sys.stdout.buffer.write(replace_prefix(SOXI_HELP, prog))
                        sys.stdout.buffer.flush()
                        sys.exit(1)
                    else:
                        sys.stderr.write(f"{prog} WARN getopt: option `{ch}' not recognized\n")
                        sys.stdout.buffer.write(replace_prefix(SOXI_HELP, prog))
                        sys.stdout.buffer.flush()
                        sys.exit(1)
                i+=1
                continue
        else:
            infiles.append(a); i+=1
    if not infiles:
        sys.stdout.buffer.write(replace_prefix(SOXI_HELP, prog))
        sys.stdout.buffer.flush()
        sys.exit(0)
    # Now process files
    def format_duration(seconds):
        h = int(seconds // 3600)
        m = int((seconds % 3600)//60)
        s = seconds % 60
        return f"{h:02d}:{m:02d}:{s:05.2f}"
    def parse_wav_info(path):
        data = open(path, "rb").read()
        if len(data)<12 or data[0:4]!=b'RIFF' or data[8:12]!=b'WAVE':
            raise Exception(f"bad input format for file `{path}': sample rate zero or negative")
        pos=12
        fmt=None
        data_chunk_size=None
        data_chunk_pos=None
        fact_samples=None
        while pos+8 <= len(data):
            cid=data[pos:pos+4]
            csize=struct.unpack("<I", data[pos+4:pos+8])[0]
            if cid==b'fmt ':
                fmt_data=data[pos+8:pos+8+csize]
                if len(fmt_data)<16:
                    raise Exception(f"bad input format for file `{path}': sample rate zero or negative")
                wFormatTag,nChannels,nSampleRate,nAvgBytesPerSec,nBlockAlign,wBitsPerSample = struct.unpack("<HHIIHH", fmt_data[:16])
                fmt={"wFormatTag":wFormatTag,"nChannels":nChannels,"nSampleRate":nSampleRate,"nAvgBytesPerSec":nAvgBytesPerSec,"nBlockAlign":nBlockAlign,"wBitsPerSample":wBitsPerSample,"csize":csize,"fmt_data":fmt_data}
                if nSampleRate==0:
                    raise Exception(f"bad input format for file `{path}': sample rate zero or negative")
            elif cid==b'fact':
                if csize>=4:
                    fact_samples=struct.unpack("<I", data[pos+8:pos+12])[0]
            elif cid==b'data':
                data_chunk_size=csize
                data_chunk_pos=pos+8
                break
            pos+=8+csize
            if csize%2==1: pos+=1
        if fmt is None or data_chunk_size is None:
            raise Exception(f"bad input format for file `{path}': sample rate zero or negative")
        nChannels=fmt["nChannels"]
        wBitsPerSample=fmt["wBitsPerSample"]
        nSampleRate=fmt["nSampleRate"]
        block_align=fmt["nBlockAlign"]
        if block_align==0:
            block_align=nChannels*(wBitsPerSample//8)
        n_frames=data_chunk_size//block_align if block_align else 0
        if fact_samples is not None and fact_samples!=0:
            n_frames=fact_samples
        file_size=os.path.getsize(path)
        duration_sec=n_frames/nSampleRate if nSampleRate else 0
        if wBitsPerSample==8:
            encoding="Unsigned Integer PCM"
        elif wBitsPerSample in (16,24,32):
            encoding="Signed Integer PCM"
        else:
            encoding="Signed Integer PCM"
        if fmt["wFormatTag"]==3:
            encoding="Floating Point PCM"
        info={"path":path,"channels":nChannels,"rate":nSampleRate,"bits":wBitsPerSample,"samples":n_frames,"duration":duration_sec,"file_size":file_size,"encoding":encoding,"precision":wBitsPerSample}
        return info
    def get_file_info(path):
        if not os.path.exists(path):
            return None, f"can't open input file `{path}': No such file or directory"
        try:
            info=parse_wav_info(path)
            return info,None
        except Exception as e:
            return None,str(e)
    total_samples=0
    total_duration=0
    infos=[]
    for path in infiles:
        info,err=get_file_info(path)
        if err:
            sys.stderr.write(f"{prog} FAIL formats: {err}\n")
            sys.exit(1)
        infos.append(info)
        total_samples+=info["samples"]
        total_duration+=info["duration"]
        if verbosity>=3:
            sys.stderr.write(f"{prog} INFO formats: detected file format type `wav'\n")
            if info["bits"]==32:
                sys.stderr.write(f"{prog} INFO wav: EXTENSIBLE\n")
    if mode is None:
        for info in infos:
            fs=info["file_size"]
            if fs<1000:
                fs_str=f"{fs}"
            elif fs<10000:
                fs_str=f"{fs/1000:.2f}k"
            else:
                fs_str=f"{fs/1000:.1f}k"
            if info["duration"]>0:
                br=info["file_size"]*8/info["duration"]/1000
                br_str=f"{int(round(br))}k"
            else:
                br_str="0k"
            dur_str=format_duration(info["duration"])
            if info["rate"]!=0:
                sectors=info["samples"]*44100/info["rate"]/588
            else:
                sectors=0
            if abs(sectors-round(sectors))<0.001:
                sectors_str=f"{int(round(sectors))}"
            else:
                sectors_str=f"{sectors:.1f}"
            out_lines=[]
            out_lines.append(f"\nInput File     : '{info['path']}'")
            out_lines.append(f"Channels       : {info['channels']}")
            out_lines.append(f"Sample Rate    : {info['rate']}")
            out_lines.append(f"Precision      : {info['bits']}-bit")
            out_lines.append(f"Duration       : {dur_str} = {info['samples']} samples ~ {sectors_str} CDDA sectors")
            out_lines.append(f"File Size      : {fs_str}")
            out_lines.append(f"Bit Rate       : {br_str}")
            out_lines.append(f"Sample Encoding: {info['bits']}-bit {info['encoding']}")
            sys.stdout.write("\n".join(out_lines)+"\n")
        if len(infos)>1:
            total_dur_str=format_duration(total_duration)
            sys.stdout.write(f"\nTotal Duration of {len(infos)} files: {total_dur_str}\n")
        sys.stdout.flush()
        sys.exit(0)
    else:
        outputs=[]
        for info in infos:
            if mode=='t':
                outputs.append("wav")
            elif mode=='r':
                outputs.append(str(info["rate"]))
            elif mode=='c':
                outputs.append(str(info["channels"]))
            elif mode=='s':
                outputs.append(str(info["samples"]))
            elif mode=='d':
                outputs.append(format_duration(info["duration"]))
            elif mode=='D':
                outputs.append(f"{info['duration']:.6f}")
            elif mode=='b':
                outputs.append(str(info["bits"]))
            elif mode=='B':
                if info["duration"]>0:
                    br=info["file_size"]*8/info["duration"]/1000
                    outputs.append(f"{int(round(br))}k")
                else:
                    outputs.append("0k")
            elif mode=='p':
                outputs.append(str(info["precision"]))
            elif mode=='e':
                outputs.append(info["encoding"])
            elif mode=='a':
                outputs.append("")
            else:
                outputs.append("")
        if show_totals and mode in 'sDd':
            if mode=='s':
                total_s=sum(info["samples"] for info in infos)
                sys.stdout.write(f"{float(total_s):.6f}\n")
            elif mode=='D':
                total_D=sum(info["duration"] for info in infos)
                sys.stdout.write(f"{total_D:.6f}\n")
            elif mode=='d':
                total_dur_str=format_duration(total_duration)
                sys.stdout.write(f"{total_dur_str}\n")
            sys.stdout.flush()
            sys.exit(0)
        else:
            for out in outputs:
                sys.stdout.write(out+"\n")
            sys.stdout.flush()
            sys.exit(0)

# Helper functions for wav
def parse_wav_info_for_effect(path):
    # same as above but simpler
    data=open(path,"rb").read()
    if len(data)<12 or data[0:4]!=b'RIFF' or data[8:12]!=b'WAVE':
        raise Exception(f"bad input format for file `{path}': sample rate zero or negative")
    pos=12
    fmt=None
    data_chunk_size=None
    data_chunk_pos=None
    fact_samples=None
    while pos+8 <= len(data):
        cid=data[pos:pos+4]
        csize=struct.unpack("<I", data[pos+4:pos+8])[0]
        if cid==b'fmt ':
            fmt_data=data[pos+8:pos+8+csize]
            wFormatTag,nChannels,nSampleRate,nAvgBytesPerSec,nBlockAlign,wBitsPerSample = struct.unpack("<HHIIHH", fmt_data[:16])
            fmt={"wFormatTag":wFormatTag,"nChannels":nChannels,"nSampleRate":nSampleRate,"nAvgBytesPerSec":nAvgBytesPerSec,"nBlockAlign":nBlockAlign,"wBitsPerSample":wBitsPerSample}
            if nSampleRate==0:
                raise Exception(f"bad input format for file `{path}': sample rate zero or negative")
        elif cid==b'fact':
            if csize>=4:
                fact_samples=struct.unpack("<I", data[pos+8:pos+12])[0]
        elif cid==b'data':
            data_chunk_size=csize
            data_chunk_pos=pos+8
            break
        pos+=8+csize
        if csize%2==1: pos+=1
    if fmt is None or data_chunk_size is None:
        raise Exception(f"bad input format for file `{path}': sample rate zero or negative")
    nChannels=fmt["nChannels"]
    wBitsPerSample=fmt["wBitsPerSample"]
    nSampleRate=fmt["nSampleRate"]
    block_align=fmt["nBlockAlign"]
    if block_align==0:
        block_align=nChannels*(wBitsPerSample//8)
    n_frames=data_chunk_size//block_align if block_align else 0
    if fact_samples is not None and fact_samples!=0:
        n_frames=fact_samples
    file_size=os.path.getsize(path)
    return fmt, n_frames, file_size, data, data_chunk_pos, data_chunk_size

def read_wav_samples(path, fmt, n_frames, data, data_pos, data_size):
    wBitsPerSample=fmt["wBitsPerSample"]
    nChannels=fmt["nChannels"]
    block_align=fmt["nBlockAlign"]
    if block_align==0:
        block_align=nChannels*(wBitsPerSample//8)
    raw=data[data_pos:data_pos+data_size]
    # Trim to exact frames
    n_frames_actual=len(raw)//block_align
    # Convert to float samples in [-1,1]
    samples=[]
    if wBitsPerSample==8:
        # 8-bit unsigned
        for i in range(n_frames_actual):
            for ch in range(nChannels):
                off=i*block_align+ch*1
                val=raw[off]
                f=(val-128)/128.0
                samples.append(f)
        # But need per channel interleaved? We'll store as list of frames, each frame is list of channel values
        # For simplicity, flatten
        # We'll return as list of lists
        # Regenerate structure
        frames=[]
        for i in range(n_frames_actual):
            frame=[]
            for ch in range(nChannels):
                off=i*block_align+ch*1
                val=raw[off]
                f=(val-128)/128.0
                frame.append(f)
            frames.append(frame)
        return frames
    elif wBitsPerSample==16:
        frames=[]
        for i in range(n_frames_actual):
            frame=[]
            for ch in range(nChannels):
                off=i*block_align+ch*2
                val=struct.unpack("<h", raw[off:off+2])[0]
                f=val/32768.0
                frame.append(f)
            frames.append(frame)
        return frames
    elif wBitsPerSample==32:
        frames=[]
        for i in range(n_frames_actual):
            frame=[]
            for ch in range(nChannels):
                off=i*block_align+ch*4
                val=struct.unpack("<i", raw[off:off+4])[0]
                f=val/2147483647.0
                frame.append(f)
            frames.append(frame)
        return frames
    elif wBitsPerSample==24:
        frames=[]
        for i in range(n_frames_actual):
            frame=[]
            for ch in range(nChannels):
                off=i*block_align+ch*3
                b=raw[off:off+3]
                # Little endian 24-bit
                val=b[0]|(b[1]<<8)|(b[2]<<16)
                if val & 0x800000:
                    val-=1<<24
                f=val/8388608.0
                frame.append(f)
            frames.append(frame)
        return frames
    else:
        # fallback
        return [[0.0]*nChannels for _ in range(n_frames_actual)]

def write_wav(path, frames, sample_rate, bits, channels):
    # frames: list of [ch values] float in [-1,1]
    # bits: 8,16,24,32
    # channels: int
    # If path == "-" write to stdout
    # Determine format tag
    if bits==8:
        wFormatTag=1
        block_align=channels*1
        avg_bytes=sample_rate*block_align
