        for fr in frames:
            for ch in range(channels):
                if ch < len(fr):
                    v=fr[ch]
                else:
                    v=0.0
                # Clamp
                if v>1.0: v=1.0
                if v<-1.0: v=-1.0
                val=int((v*128)+128)
                if val<0: val=0
                if val>255: val=255
