        fmt_chunk_size=16
        fmt_data=struct.pack("<HHIIHH", wFormatTag, channels, sample_rate, avg_bytes, block_align, wBitsPerSample)
        fact_needed=False
    elif bits==16:
        wFormatTag=1
        block_align=channels*2
        avg_bytes=sample_rate*block_align
        data_bytes=bytearray()
        for fr in frames:
            for ch in range(channels):
                v=fr[ch] if ch < len(fr) else 0.0
                if v>1.0: v=1.0
                if v<-1.0: v=-1.0
                val=int(v*32767)  # use 32767 as in SoX? For 16-bit, they use 32767?
                # For -1.0, need -32768?
                if v==-1.0:
                    val=-32768
                data_bytes+=struct.pack("<h", val)
        wBitsPerSample=16
        fmt_chunk_size=16
        fmt_data=struct.pack("<HHIIHH", wFormatTag, channels, sample_rate, avg_bytes, block_align, wBitsPerSample)
        fact_needed=False
    else:
        # For 24,32 use extensible
        # Use WAVE_FORMAT_EXTENSIBLE 65534
        wFormatTag=65534
        if bits==24:
            block_align=channels*3
        else:
            block_align=channels*4
            bits=32
        avg_bytes=sample_rate*block_align
        wBitsPerSample=bits
        data_bytes=bytearray()
        for fr in frames:
            for ch in range(channels):
                v=fr[ch] if ch < len(fr) else 0.0
                if v>1.0: v=1.0
                if v<-1.0: v=-1.0
                if bits==24:
                    val=int(v*8388607)
                    if val<0:
                        val+=1<<24
                    data_bytes.append(val & 0xFF)
                    data_bytes.append((val>>8) & 0xFF)
                    data_bytes.append((val>>16) & 0xFF)
                else:
                    val=int(v*2147483647)
                    if v==-1.0:
                        val=-2147483648
                    data_bytes+=struct.pack("<i", val)
        # Extensible fmt chunk: size 40
        fmt_chunk_size=40
        # GUID for PCM: {00000001-0000-0010-8000-00AA00389B71}
        # Need to pack extensible: wFormatTag 65534, nChannels, nSampleRate, nAvgBytesPerSec, nBlockAlign, wBitsPerSample, cbSize 22, wValidBitsPerSample, dwChannelMask, SubFormat GUID
        cbSize=22
        wValidBitsPerSample=bits
        # Channel mask: for mono 0x4, stereo 0x3, etc. Use 0 for now? Original uses mask based on channels: for mono 0x4? For stereo 0x3? Let's use simple.
        if channels==1:
            dwChannelMask=0x00000004
        elif channels==2:
            dwChannelMask=0x00000003
        else:
            dwChannelMask=0
        # SubFormat: PCM GUID
        guid = bytes.fromhex("0100000000001000800000AA00389B71") # little endian? Actually need to check byte order: original extensible fmt_data after 16 bytes: 22 00 ... Let's replicate observed hex: for 32-bit mono 48000, fmt_data was feff010080bb000000ee02000400200016002000040000000100000000001000800000aa00389b71
        # Let's construct matching observed: after standard 16 bytes (fe ff 01 00 80 bb 00 00 00 ee 02 00 04 00 20 00) then 16 00 20 00 04 00 00 00 01 00 00 00 00 00 10 00 80 00 00 aa 00 38 9b 71
        # So we will construct similar.
        # Pack: standard 16 + cbSize(2) + wValidBits(2) + dwChannelMask(4) + SubFormat GUID (16)
        fmt_data=struct.pack("<HHIIHH", wFormatTag, channels, sample_rate, avg_bytes, block_align, wBitsPerSample)
        fmt_data+=struct.pack("<H", cbSize)
        fmt_data+=struct.pack("<H", wValidBitsPerSample)
        fmt_data+=struct.pack("<I", dwChannelMask)
        # GUID: Data1 00000001, Data2 0000, Data3 0010, Data4 8000 00AA00389B71
        # Packed as little endian for Data1-3? The GUID bytes in file are as observed: 01 00 00 00 00 00 10 00 80 00 00 aa 00 38 9b 71
        # That matches little endian for Data1 (01 00 00 00), Data2 (00 00), Data3 (10 00), then Data4 (80 00 00 aa 00 38 9b 71)
        fmt_data+=struct.pack("<I", 0x00000001)
        fmt_data+=struct.pack("<H", 0x0000)
        fmt_data+=struct.pack("<H", 0x0010)
        fmt_data+=bytes.fromhex("800000AA00389B71")
        fact_needed=True

    # Determine if output is stdout pipe
    data_len=len(data_bytes)
    # For extensible, need fact chunk
    out_bytes=bytearray()
    out_bytes+=b'RIFF'
    # Placeholder for file size
    # Total size = 4 (WAVE) + (8+fmt_size) + (8+4 if fact) + (8+data_len)
    # RIFF size = total -8
    if fact_needed:
        # fact chunk is 4 bytes with nFrames
        n_frames=len(frames)
        fact_data=struct.pack("<I", n_frames)
        riff_size=4 + (8+fmt_chunk_size) + (8+4) + (8+data_len)
    else:
        riff_size=4 + (8+fmt_chunk_size) + (8+data_len)
    out_bytes+=struct.pack("<I", riff_size)
    out_bytes+=b'WAVE'
    out_bytes+=b'fmt '
    out_bytes+=struct.pack("<I", fmt_chunk_size)
    out_bytes+=fmt_data
    if fact_needed:
        out_bytes+=b'fact'
        out_bytes+=struct.pack("<I", 4)
        out_bytes+=fact_data
    out_bytes+=b'data'
    # For pipe stdout with can't seek, SoX warns length wrong; but we still write correct length
    # For pipe, data_len may be placeholder? Original for pipe wrote data length 0 and warned. But we will write correct.
    out_bytes+=struct.pack("<I", data_len)
    out_bytes+=data_bytes
    if path=="-":
        # Write to stdout
        # Need to handle warning if pipe
        sys.stderr.write(f"{sys.argv[0]} WARN wav: Length in output .wav header will be wrong since can't seek to fix it\n")
        sys.stdout.buffer.write(out_bytes)
        sys.stdout.buffer.flush()
    else:
        # Handle no-clobber etc already checked outside
        with open(path, "wb") as f:
            f.write(out_bytes)

