# Helper functions for wav
def parse_wav_info_for_effect(path):
    # same as above but simpler
    data=open(path,"rb").read()
    if len(data)<12 or data[0:4]!=b'RIFF' or data[8:12]!=b'WAVE':
        raise Exception(f"bad input format for file `{path}': sample rate zero or negative")
    pos=12
    fmt=None
    data_chunk_size=None
    data_chunk_pos=None
    fact_samples=None
    while pos+8 <= len(data):
        cid=data[pos:pos+4]
        csize=struct.unpack("<I", data[pos+4:pos+8])[0]
        if cid==b'fmt ':
            fmt_data=data[pos+8:pos+8+csize]
            wFormatTag,nChannels,nSampleRate,nAvgBytesPerSec,nBlockAlign,wBitsPerSample = struct.unpack("<HHIIHH", fmt_data[:16])
            fmt={"wFormatTag":wFormatTag,"nChannels":nChannels,"nSampleRate":nSampleRate,"nAvgBytesPerSec":nAvgBytesPerSec,"nBlockAlign":nBlockAlign,"wBitsPerSample":wBitsPerSample}
            if nSampleRate==0:
                raise Exception(f"bad input format for file `{path}': sample rate zero or negative")
        elif cid==b'fact':
            if csize>=4:
                fact_samples=struct.unpack("<I", data[pos+8:pos+12])[0]
        elif cid==b'data':
            data_chunk_size=csize
            data_chunk_pos=pos+8
            break
        pos+=8+csize
        if csize%2==1: pos+=1
    if fmt is None or data_chunk_size is None:
        raise Exception(f"bad input format for file `{path}': sample rate zero or negative")
    nChannels=fmt["nChannels"]
    wBitsPerSample=fmt["wBitsPerSample"]
    nSampleRate=fmt["nSampleRate"]
    block_align=fmt["nBlockAlign"]
    if block_align==0:
        block_align=nChannels*(wBitsPerSample//8)
    n_frames=data_chunk_size//block_align if block_align else 0
    if fact_samples is not None and fact_samples!=0:
        n_frames=fact_samples
    file_size=os.path.getsize(path)
    return fmt, n_frames, file_size, data, data_chunk_pos, data_chunk_size

def read_wav_samples(path, fmt, n_frames, data, data_pos, data_size):
    wBitsPerSample=fmt["wBitsPerSample"]
    nChannels=fmt["nChannels"]
    block_align=fmt["nBlockAlign"]
    if block_align==0:
        block_align=nChannels*(wBitsPerSample//8)
    raw=data[data_pos:data_pos+data_size]
    # Trim to exact frames
    n_frames_actual=len(raw)//block_align
    # Convert to float samples in [-1,1]
    samples=[]
    if wBitsPerSample==8:
        # 8-bit unsigned
        for i in range(n_frames_actual):
            for ch in range(nChannels):
                off=i*block_align+ch*1
                val=raw[off]
                f=(val-128)/128.0
                samples.append(f)
        # But need per channel interleaved? We'll store as list of frames, each frame is list of channel values
        # For simplicity, flatten
        # We'll return as list of lists
        # Regenerate structure
        frames=[]
        for i in range(n_frames_actual):
            frame=[]
            for ch in range(nChannels):
                off=i*block_align+ch*1
                val=raw[off]
                f=(val-128)/128.0
                frame.append(f)
            frames.append(frame)
        return frames
    elif wBitsPerSample==16:
        frames=[]
        for i in range(n_frames_actual):
            frame=[]
            for ch in range(nChannels):
                off=i*block_align+ch*2
                val=struct.unpack("<h", raw[off:off+2])[0]
                f=val/32768.0
                frame.append(f)
            frames.append(frame)
        return frames
    elif wBitsPerSample==32:
        frames=[]
        for i in range(n_frames_actual):
            frame=[]
            for ch in range(nChannels):
                off=i*block_align+ch*4
                val=struct.unpack("<i", raw[off:off+4])[0]
                f=val/2147483647.0
                frame.append(f)
            frames.append(frame)
        return frames
    elif wBitsPerSample==24:
        frames=[]
        for i in range(n_frames_actual):
            frame=[]
            for ch in range(nChannels):
                off=i*block_align+ch*3
                b=raw[off:off+3]
                # Little endian 24-bit
                val=b[0]|(b[1]<<8)|(b[2]<<16)
                if val & 0x800000:
                    val-=1<<24
                f=val/8388608.0
                frame.append(f)
            frames.append(frame)
        return frames
    else:
        # fallback
        return [[0.0]*nChannels for _ in range(n_frames_actual)]

def write_wav(path, frames, sample_rate, bits, channels):
    # frames: list of [ch values] float in [-1,1]
    # bits: 8,16,24,32
    # channels: int
    # If path == "-" write to stdout
    # Determine format tag
    if bits==8:
        wFormatTag=1
        block_align=channels*1
        avg_bytes=sample_rate*block_align
        data_bytes=bytearray()
        for fr in frames:
            for ch in range(channels):
                if ch < len(fr):
                    v=fr[ch]
                else:
                    v=0.0
                # Clamp
                if v>1.0: v=1.0
                if v<-1.0: v=-1.0
                val=int((v*128)+128)
                if val<0: val=0
                if val>255: val=255
                data_bytes.append(val)
        wBitsPerSample=8
        # Header: PCM, fmt size 16
        fmt_chunk_size=16
        fmt_data=struct.pack("<HHIIHH", wFormatTag, channels, sample_rate, avg_bytes, block_align, wBitsPerSample)
        fact_needed=False
    elif bits==16:
        wFormatTag=1
        block_align=channels*2
        avg_bytes=sample_rate*block_align
        data_bytes=bytearray()
        for fr in frames:
            for ch in range(channels):
                v=fr[ch] if ch < len(fr) else 0.0
                if v>1.0: v=1.0
                if v<-1.0: v=-1.0
                val=int(v*32767)  # use 32767 as in SoX? For 16-bit, they use 32767?
                # For -1.0, need -32768?
                if v==-1.0:
                    val=-32768
                data_bytes+=struct.pack("<h", val)
        wBitsPerSample=16
        fmt_chunk_size=16
        fmt_data=struct.pack("<HHIIHH", wFormatTag, channels, sample_rate, avg_bytes, block_align, wBitsPerSample)
        fact_needed=False
    else:
        # For 24,32 use extensible
        # Use WAVE_FORMAT_EXTENSIBLE 65534
        wFormatTag=65534
        if bits==24:
            block_align=channels*3
        else:
            block_align=channels*4
            bits=32
        avg_bytes=sample_rate*block_align
        wBitsPerSample=bits
        data_bytes=bytearray()
        for fr in frames:
            for ch in range(channels):
                v=fr[ch] if ch < len(fr) else 0.0
                if v>1.0: v=1.0
                if v<-1.0: v=-1.0
                if bits==24:
                    val=int(v*8388607)
                    if val<0:
                        val+=1<<24
                    data_bytes.append(val & 0xFF)
                    data_bytes.append((val>>8) & 0xFF)
                    data_bytes.append((val>>16) & 0xFF)
                else:
                    val=int(v*2147483647)
                    if v==-1.0:
                        val=-2147483648
                    data_bytes+=struct.pack("<i", val)
        # Extensible fmt chunk: size 40
        fmt_chunk_size=40
        # GUID for PCM: {00000001-0000-0010-8000-00AA00389B71}
        # Need to pack extensible: wFormatTag 65534, nChannels, nSampleRate, nAvgBytesPerSec, nBlockAlign, wBitsPerSample, cbSize 22, wValidBitsPerSample, dwChannelMask, SubFormat GUID
        cbSize=22
        wValidBitsPerSample=bits
        # Channel mask: for mono 0x4, stereo 0x3, etc. Use 0 for now? Original uses mask based on channels: for mono 0x4? For stereo 0x3? Let's use simple.
        if channels==1:
            dwChannelMask=0x00000004
        elif channels==2:
            dwChannelMask=0x00000003
        else:
            dwChannelMask=0
        # SubFormat: PCM GUID
        guid = bytes.fromhex("0100000000001000800000AA00389B71") # little endian? Actually need to check byte order: original extensible fmt_data after 16 bytes: 22 00 ... Let's replicate observed hex: for 32-bit mono 48000, fmt_data was feff010080bb000000ee02000400200016002000040000000100000000001000800000aa00389b71
        # Let's construct matching observed: after standard 16 bytes (fe ff 01 00 80 bb 00 00 00 ee 02 00 04 00 20 00) then 16 00 20 00 04 00 00 00 01 00 00 00 00 00 10 00 80 00 00 aa 00 38 9b 71
        # So we will construct similar.
        # Pack: standard 16 + cbSize(2) + wValidBits(2) + dwChannelMask(4) + SubFormat GUID (16)
        fmt_data=struct.pack("<HHIIHH", wFormatTag, channels, sample_rate, avg_bytes, block_align, wBitsPerSample)
        fmt_data+=struct.pack("<H", cbSize)
        fmt_data+=struct.pack("<H", wValidBitsPerSample)
        fmt_data+=struct.pack("<I", dwChannelMask)
        # GUID: Data1 00000001, Data2 0000, Data3 0010, Data4 8000 00AA00389B71
        # Packed as little endian for Data1-3? The GUID bytes in file are as observed: 01 00 00 00 00 00 10 00 80 00 00 aa 00 38 9b 71
        # That matches little endian for Data1 (01 00 00 00), Data2 (00 00), Data3 (10 00), then Data4 (80 00 00 aa 00 38 9b 71)
        fmt_data+=struct.pack("<I", 0x00000001)
        fmt_data+=struct.pack("<H", 0x0000)
        fmt_data+=struct.pack("<H", 0x0010)
        fmt_data+=bytes.fromhex("800000AA00389B71")
        fact_needed=True

    # Determine if output is stdout pipe
    data_len=len(data_bytes)
    # For extensible, need fact chunk
    out_bytes=bytearray()
    out_bytes+=b'RIFF'
    # Placeholder for file size
    # Total size = 4 (WAVE) + (8+fmt_size) + (8+4 if fact) + (8+data_len)
    # RIFF size = total -8
    if fact_needed:
        # fact chunk is 4 bytes with nFrames
        n_frames=len(frames)
        fact_data=struct.pack("<I", n_frames)
        riff_size=4 + (8+fmt_chunk_size) + (8+4) + (8+data_len)
    else:
        riff_size=4 + (8+fmt_chunk_size) + (8+data_len)
    out_bytes+=struct.pack("<I", riff_size)
    out_bytes+=b'WAVE'
    out_bytes+=b'fmt '
    out_bytes+=struct.pack("<I", fmt_chunk_size)
    out_bytes+=fmt_data
    if fact_needed:
        out_bytes+=b'fact'
        out_bytes+=struct.pack("<I", 4)
        out_bytes+=fact_data
    out_bytes+=b'data'
    # For pipe stdout with can't seek, SoX warns length wrong; but we still write correct length
    # For pipe, data_len may be placeholder? Original for pipe wrote data length 0 and warned. But we will write correct.
    out_bytes+=struct.pack("<I", data_len)
    out_bytes+=data_bytes
    if path=="-":
        # Write to stdout
        # Need to handle warning if pipe
        sys.stderr.write(f"{sys.argv[0]} WARN wav: Length in output .wav header will be wrong since can't seek to fix it\n")
        sys.stdout.buffer.write(out_bytes)
        sys.stdout.buffer.flush()
    else:
        # Handle no-clobber etc already checked outside
        with open(path, "wb") as f:
            f.write(out_bytes)

