def combine_frames(loaded, combine_mode):
    if not loaded:
        return [],48000,1
    real=[x for x in loaded if x[0] is not None]
    if not real:
        rate=loaded[0][1]
        return [], rate, 1
    if combine_mode in ("concatenate","sequence"):
        all_frames=[]
        for frames, rate, ch, bits in real:
            all_frames.extend(frames)
        return all_frames, real[0][1], real[0][2]
    elif combine_mode in ("mix","mix-power"):
        max_len=max(len(frames) for frames,_,_,_ in real)
        channels=real[0][2]
        mixed=[]
        for i in range(max_len):
            mixed_frame=[0.0]*channels
            for frames, rate, ch, bits in real:
                if i < len(frames):
                    for c in range(channels):
                        if c < len(frames[i]):
                            mixed_frame[c]+=frames[i][c]
            if combine_mode=="mix":
                for c in range(channels):
                    mixed_frame[c]/=len(real)
            else:
                for c in range(channels):
                    mixed_frame[c]/=math.sqrt(len(real))
            mixed.append(mixed_frame)
        return mixed, real[0][1], real[0][2]
    elif combine_mode=="merge":
        if len(real)==2 and real[0][2]==1 and real[1][2]==1:
            max_len=max(len(real[0][0]), len(real[1][0]))
            merged=[]
            for i in range(max_len):
                left=real[0][0][i][0] if i < len(real[0][0]) else 0.0
                right=real[1][0][i][0] if i < len(real[1][0]) else 0.0
                merged.append([left,right])
            return merged, real[0][1], 2
        else:
            return combine_frames(real, "mix")
    elif combine_mode=="multiply":
        max_len=max(len(frames) for frames,_,_,_ in real)
        channels=real[0][2]
        multiplied=[]
        for i in range(max_len):
            frame=[1.0]*channels
            for frames, rate, ch, bits in real:
                if i < len(frames):
                    for c in range(channels):
                        frame[c]*=frames[i][c] if c < len(frames[i]) else 0.0
                else:
                    for c in range(channels):
                        frame[c]*=0.0
            multiplied.append(frame)
        return multiplied, real[0][1], real[0][2]
    else:
        all_frames=[]
        for frames, rate, ch, bits in real:
            all_frames.extend(frames)
        return all_frames, real[0][1], real[0][2]

