def apply_vol(frames, gain_str, type_str=None, limiter=None):
    if type_str=="dB":
        try:
            g=float(gain_str)
            factor=10**(g/20.0)
        except:
            factor=1.0
    elif type_str=="power":
        try:
            g=float(gain_str)
            factor=math.sqrt(g)
        except:
            factor=1.0
    else:
        try:
            factor=float(gain_str)
        except:
            factor=1.0
    for fr in frames:
        for c in range(len(fr)):
            fr[c]*=factor
    return frames

def apply_gain(frames, opts, prog):
    has_n="-n" in opts
    gain_db=None
    for tok in opts:
        if tok not in ("-e","-b","-B","-r","-n","-l","-h"):
            try:
                gain_db=float(tok)
                break
            except:
                pass
    if has_n:
        peak=0.0
        for fr in frames:
            for v in fr:
                if abs(v)>peak:
                    peak=abs(v)
        if peak>0:
            scale=1.0/peak
            for fr in frames:
                for c in range(len(fr)):
                    fr[c]*=scale
    if gain_db is not None:
        factor=10**(gain_db/20.0)
        for fr in frames:
            for c in range(len(fr)):
                fr[c]*=factor
    return frames

