        else:
            def parse_time(t):
                try:
                    if ":" in t:
                        parts=t.split(":")
                        secs=0.0
                        mult=1
                        for p in reversed(parts):
                            secs+=float(p)*mult
                            mult*=60
                        return secs
                    else:
                        if t.endswith("s"):
                            t=t[:-1]
                        return float(t)
                except:
                    return None
            times=[]
            for tok in eopts:
                pt=parse_time(tok)
                if pt is None:
                    sys.stderr.write(f"{PROG} FAIL trim: Error parsing position {len(times)+1}\n")
                    sys.stderr.write(f"{PROG} FAIL trim: usage: {{position}}\n")
                    sys.exit(1)
                times.append(pt)
            if len(times)==1:
                start=times[0]
                start_frame=int(start*cur_rate)
                cur_frames=cur_frames[start_frame:]
            elif len(times)>=2:
                start=times[0]
                second=times[1]
                start_frame=int(start*cur_rate)
                length_frames=int(second*cur_rate)
                cur_frames=cur_frames[start_frame:start_frame+length_frames]
    elif ename=="reverse":
        cur_frames=list(reversed(cur_frames))
    elif ename=="channels":
        new_ch=int(eopts[0])
        if cur_channels==1 and new_ch==1:
            pass
        elif cur_channels==1 and new_ch==2:
            new_frames=[]
            for fr in cur_frames:
                val=fr[0] if fr else 0.0
                new_frames.append([val,val])
            cur_frames=new_frames
            cur_channels=2
        elif cur_channels==2 and new_ch==1:
            new_frames=[]
            for fr in cur_frames:
                val=sum(fr)/len(fr) if fr else 0.0
                new_frames.append([val])
            cur_frames=new_frames
            cur_channels=1
        else:
            new_frames=[]
            for fr in cur_frames:
                new_fr=[]
                for c in range(new_ch):
                    if c < len(fr):
                        new_fr.append(fr[c])
                    else:
                        new_fr.append(fr[0] if fr else 0.0)
                new_frames.append(new_fr)
            cur_frames=new_frames
            cur_channels=new_ch
    elif ename=="remix":
        if eopts:
            spec=" ".join(eopts)
            if spec.strip()=="1":
                new_frames=[]
                for fr in cur_frames:
                    val=fr[0] if len(fr)>0 else 0.0
                    new_frames.append([val])
                cur_frames=new_frames
                cur_channels=1
    elif ename=="rate":
        target_rate=None
        for tok in eopts:
            if tok in ("-q","-l","-m","-h","-v","-s","-a","-M","-I","-L","-b"):
                continue
            if tok.startswith("-"):
                continue
            try:
                if tok.lower().endswith("k"):
                    target_rate=int(float(tok[:-1])*1000)
                else:
                    target_rate=int(float(tok))
                break
