        old_len=len(cur_frames)
        new_len=int(old_len*target_rate/cur_rate)
        new_frames=[]
        for i in range(new_len):
            src_pos=i*cur_rate/target_rate
            idx0=int(math.floor(src_pos))
            idx1=min(idx0+1, old_len-1)
            frac=src_pos-idx0
            if idx0>=old_len:
                new_frames.append([0.0]*cur_channels)
                continue
            fr0=cur_frames[idx0]
            fr1=cur_frames[idx1]
            new_fr=[]
            for c in range(cur_channels):
                v0=fr0[c] if c < len(fr0) else 0.0
                v1=fr1[c] if c < len(fr1) else 0.0
                new_fr.append(v0*(1-frac)+v1*frac)
            new_frames.append(new_fr)
        clip_count=0
        for fr in new_frames:
            for v in fr:
                if abs(v)>1.0:
                    clip_count+=1
        if clip_count>0 and not global_opts["quiet"] and global_opts["verbosity"]>=2:
            sys.stderr.write(f"{PROG} WARN rate: rate clipped {clip_count} samples; decrease volume?\n")
        cur_frames=new_frames
        cur_rate=target_rate
    elif ename=="norm":
        peak=0.0
        for fr in cur_frames:
            for v in fr:
                if abs(v)>peak:
                    peak=abs(v)
        if peak>0:
            scale=1.0/peak
            if eopts:
                try:
                    lvl=float(eopts[0])
                    scale*=10**(lvl/20.0)
                except:
                    pass
            for fr in cur_frames:
                for c in range(len(fr)):
                    fr[c]*=scale
    elif ename=="swap":
        for fr in cur_frames:
            if len(fr)>=2:
                fr[0],fr[1]=fr[1],fr[0]
    elif ename=="dcshift":
        if eopts:
            try:
