def apply_vol(frames, gain_str, type_str=None, limiter=None):
    if type_str=="dB":
        try:
            g=float(gain_str)
            factor=10**(g/20.0)
        except:
            factor=1.0
    elif type_str=="power":
        try:
            g=float(gain_str)
            factor=math.sqrt(g)
        except:
            factor=1.0
    else:
        try:
            factor=float(gain_str)
        except:
            factor=1.0
    for fr in frames:
        for c in range(len(fr)):
            fr[c]*=factor
    return frames

def apply_gain(frames, opts, prog):
    has_n="-n" in opts
    gain_db=None
    for tok in opts:
        if tok not in ("-e","-b","-B","-r","-n","-l","-h"):
            try:
                gain_db=float(tok)
                break
            except:
                pass
    if has_n:
        peak=0.0
        for fr in frames:
            for v in fr:
                if abs(v)>peak:
                    peak=abs(v)
        if peak>0:
            scale=1.0/peak
            for fr in frames:
                for c in range(len(fr)):
                    fr[c]*=scale
    if gain_db is not None:
        factor=10**(gain_db/20.0)
        for fr in frames:
            for c in range(len(fr)):
                fr[c]*=factor
    return frames

for ename,eopts in effects_to_apply:
    if ename=="earwax":
        if cur_channels!=2 or cur_rate!=44100:
            sys.stderr.write(f"{PROG} FAIL earwax: works only with stereo audio sampled at 44100Hz (i.e. CDDA)\n")
            sys.exit(2)
    if ename=="vol":
        gain=eopts[0] if len(eopts)>=1 else "1"
        typ=eopts[1] if len(eopts)>=2 else None
        lim=eopts[2] if len(eopts)>=3 else None
        cur_frames=apply_vol(cur_frames, gain, typ, lim)
    elif ename=="gain":
        cur_frames=apply_gain(cur_frames, eopts, PROG)
    elif ename=="trim":
        if not eopts:
            pass
        else:
            def parse_time(t):
                try:
                    if ":" in t:
                        parts=t.split(":")
                        secs=0.0
                        mult=1
                        for p in reversed(parts):
                            secs+=float(p)*mult
                            mult*=60
                        return secs
                    else:
                        if t.endswith("s"):
                            t=t[:-1]
                        return float(t)
                except:
                    return None
            times=[]
            for tok in eopts:
                pt=parse_time(tok)
                if pt is None:
                    sys.stderr.write(f"{PROG} FAIL trim: Error parsing position {len(times)+1}\n")
                    sys.stderr.write(f"{PROG} FAIL trim: usage: {{position}}\n")
                    sys.exit(1)
                times.append(pt)
            if len(times)==1:
                start=times[0]
                start_frame=int(start*cur_rate)
                cur_frames=cur_frames[start_frame:]
            elif len(times)>=2:
                start=times[0]
                second=times[1]
                start_frame=int(start*cur_rate)
                length_frames=int(second*cur_rate)
                cur_frames=cur_frames[start_frame:start_frame+length_frames]
    elif ename=="reverse":
        cur_frames=list(reversed(cur_frames))
    elif ename=="channels":
        new_ch=int(eopts[0])
        if cur_channels==1 and new_ch==1:
            pass
        elif cur_channels==1 and new_ch==2:
            new_frames=[]
            for fr in cur_frames:
                val=fr[0] if fr else 0.0
                new_frames.append([val,val])
            cur_frames=new_frames
            cur_channels=2
        elif cur_channels==2 and new_ch==1:
            new_frames=[]
            for fr in cur_frames:
                val=sum(fr)/len(fr) if fr else 0.0
                new_frames.append([val])
            cur_frames=new_frames
            cur_channels=1
        else:
            new_frames=[]
            for fr in cur_frames:
                new_fr=[]
                for c in range(new_ch):
                    if c < len(fr):
                        new_fr.append(fr[c])
                    else:
                        new_fr.append(fr[0] if fr else 0.0)
                new_frames.append(new_fr)
            cur_frames=new_frames
            cur_channels=new_ch
    elif ename=="remix":
        if eopts:
            spec=" ".join(eopts)
            if spec.strip()=="1":
                new_frames=[]
                for fr in cur_frames:
                    val=fr[0] if len(fr)>0 else 0.0
                    new_frames.append([val])
                cur_frames=new_frames
                cur_channels=1
    elif ename=="rate":
        target_rate=None
        for tok in eopts:
            if tok in ("-q","-l","-m","-h","-v","-s","-a","-M","-I","-L","-b"):
                continue
            if tok.startswith("-"):
                continue
            try:
                if tok.lower().endswith("k"):
                    target_rate=int(float(tok[:-1])*1000)
                else:
                    target_rate=int(float(tok))
                break
            except:
                continue
        if target_rate is None:
            continue
        if target_rate==cur_rate:
            cur_rate=target_rate
            continue
        old_len=len(cur_frames)
        new_len=int(old_len*target_rate/cur_rate)
        new_frames=[]
        for i in range(new_len):
            src_pos=i*cur_rate/target_rate
            idx0=int(math.floor(src_pos))
            idx1=min(idx0+1, old_len-1)
            frac=src_pos-idx0
            if idx0>=old_len:
                new_frames.append([0.0]*cur_channels)
                continue
            fr0=cur_frames[idx0]
            fr1=cur_frames[idx1]
            new_fr=[]
            for c in range(cur_channels):
                v0=fr0[c] if c < len(fr0) else 0.0
                v1=fr1[c] if c < len(fr1) else 0.0
                new_fr.append(v0*(1-frac)+v1*frac)
            new_frames.append(new_fr)
        clip_count=0
        for fr in new_frames:
            for v in fr:
                if abs(v)>1.0:
                    clip_count+=1
        if clip_count>0 and not global_opts["quiet"] and global_opts["verbosity"]>=2:
            sys.stderr.write(f"{PROG} WARN rate: rate clipped {clip_count} samples; decrease volume?\n")
        cur_frames=new_frames
        cur_rate=target_rate
    elif ename=="norm":
        peak=0.0
        for fr in cur_frames:
            for v in fr:
                if abs(v)>peak:
                    peak=abs(v)
        if peak>0:
            scale=1.0/peak
            if eopts:
                try:
                    lvl=float(eopts[0])
                    scale*=10**(lvl/20.0)
                except:
                    pass
            for fr in cur_frames:
                for c in range(len(fr)):
                    fr[c]*=scale
    elif ename=="swap":
        for fr in cur_frames:
            if len(fr)>=2:
                fr[0],fr[1]=fr[1],fr[0]
    elif ename=="dcshift":
        if eopts:
            try:
                shift=float(eopts[0])
                for fr in cur_frames:
                    for c in range(len(fr)):
                        fr[c]+=shift
            except:
                pass
    elif ename=="downsample":
        if eopts and eopts[0].isdigit():
            factor=int(eopts[0])
            cur_frames=cur_frames[::factor]
            cur_rate=cur_rate//factor if cur_rate else cur_rate
    elif ename=="speed":
        if eopts:
            try:
                factor=float(eopts[0].rstrip('c'))
                new_len=int(len(cur_frames)/factor)
                old_len=len(cur_frames)
                new_frames=[]
                for i in range(new_len):
                    src_pos=i*factor
                    idx0=int(math.floor(src_pos))
                    idx1=min(idx0+1, old_len-1)
                    frac=src_pos-idx0
                    if idx0>=old_len:
                        new_frames.append([0.0]*cur_channels)
                        continue
                    fr0=cur_frames[idx0]
                    fr1=cur_frames[idx1]
                    new_fr=[]
                    for c in range(cur_channels):
                        v0=fr0[c] if c < len(fr0) else 0.0
                        v1=fr1[c] if c < len(fr1) else 0.0
                        new_fr.append(v0*(1-frac)+v1*frac)
                    new_frames.append(new_fr)
                cur_frames=new_frames
            except:
                pass

